async updateTransporte(
    fechaSalidaId: string,
    transporteId: string,
    dto: UpdateTransporteAdicionalDto,
  ): Promise<TransporteAdicional> {
    const transporte =
      await this.fechasSalidaRepository.findTransporteById(transporteId);
